actions.script:
const page = ec.context.get('sitePage')
const wiki = page && page.wikiPageId ? ec.entity.find('moqui.resource.wiki.WikiPage').condition('wikiPageId', page.wikiPageId).disableAuthz().one() : null
const space = wiki ? ec.entity.find('moqui.resource.wiki.WikiSpace').condition('wikiSpaceId', wiki.wikiSpaceId).disableAuthz().one() : null
if (!page || !wiki || !space) { ec.web.sendJsonResponse({spaceList: [], recentList: [], reviewCount: 0, me: {}, commerce: null}); return }
const can = ec.context.get('pagesCan') || {}
ec.web.sendJsonResponse({spaceList: [{wikiSpaceId: space.wikiSpaceId, description: space.description || space.wikiSpaceId, canUpdate: false,
        readOnly: false}], defaultWikiSpaceId: space.wikiSpaceId, recentList: [], reviewCount: 0, me: {},
    commerce: {sitePageId: page.sitePageId, wikiPageId: wiki.wikiPageId, wikiSpaceId: wiki.wikiSpaceId, pagePath: wiki.pagePath || '',
        title: page.title, canEdit: !!can.themeEdit}})

const bound = ec.context.get('sitePage')
if (!bound || !bound.wikiPageId) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#PageView').parameters({wikiPageId: bound.wikiPageId,
    versionName: versionName || null}).call()
if (ec.message.hasError() || !out.page) { ec.web.sendJsonResponse({}); return }
const page = Object.assign({}, out.page, {canUpdate: false, title: out.page.title || bound.title})
ec.web.sendJsonResponse({page: page, failedParts: out.failedParts})

const bound = ec.context.get('sitePage')
if (!bound || !bound.wikiPageId) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#History').parameters({wikiPageId: bound.wikiPageId}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {versionList: out.versionList, historyList: out.historyList,
    currentVersionName: out.currentVersionName, publishedVersionName: out.publishedVersionName, storage: out.storage,
    canRestore: false, canPublish: false})

const bound = ec.context.get('sitePage')
if (!bound || !bound.wikiPageId) { ec.web.sendJsonResponse({}); return }
const out = ec.service.sync().name('ironstone.commons.KnowledgeServices.get#VersionDiff').parameters({wikiPageId: bound.wikiPageId,
    fromVersionName: fromVersionName || null, toVersionName: toVersionName || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {fromVersionName: out.fromVersionName, toVersionName: out.toVersionName,
    fromShort: out.fromShort, toShort: out.toShort, html: out.html, stats: out.stats})

const bound = ec.context.get('sitePage')
const out = bound && bound.wikiPageId ? ec.service.sync().name('ironstone.commons.KnowledgeServices.get#Attachment').parameters({
    wikiPageId: bound.wikiPageId, filename: filename || ''}).call() : null
if (!out || ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const out = ec.service.sync().name('mantle.public.ThemeServices.store#SitePage').parameters({sitePageId: sitePageId || '',
    pageText: pageText ?? '', versionNote: versionNote || null, baseVersionName: baseVersionName || null,
    force: String(force) === 'true'}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const short = (name) => String(name).length > 12 ? String(name).substring(0, 10) : name
const message = out.conflict ? null : out.versionName ? ec.resource.expand('Saved as version ${name}; publish it to show it on the site', '',
    {name: short(out.versionName)}) : ec.l10n.localize('No changes to save')
ec.web.sendJsonResponse({versionName: out.versionName, currentVersionName: out.currentVersionName, conflict: !!out.conflict,
    conflictText: out.conflictText, savedText: ec.l10n.format(ec.user.nowTimestamp, 'h:mm a'),
    messageInfos: message ? [{type: 'success', message: message}] : []})
